如何编写一个C#程序，计算给定笛卡尔坐标系下两点之间的欧几里得距离（点A(2,3)和点B(5,7)）？以下是该程序的C#代码：
using System;
public class Program {
    public static void Main() {
        int x1 = 2, y1 = 3, x2 = 5, y2 = 7;
        double distance = Math.Sqrt(Math.Pow(x2-x1,2) + Math.Pow(y2-y1,2));
        Console.WriteLine("点A(2,3)和点B(5,7)之间的欧几里得距离为：" + distance);
    }
} 
如何修改这个代码，以接受用户输入点A和点B的坐标？

以下是修改后的代码，使用Console.ReadLine()方法接受用户输入的坐标：
using System;
public class Program {
    public static void Main() {
        Console.WriteLine("请输入点A的坐标，格式为x,y：");
        string inputA = Console.ReadLine();
        string[] coordinatesA = inputA.Split(',');
        int x1 = int.Parse(coordinatesA[0]);
        int y1 = int.Parse(coordinatesA[1]);

        Console.WriteLine("请输入点B的坐标，格式为x,y：");
        string inputB = Console.ReadLine();
        string[] coordinatesB = inputB.Split(',');
        int x2 = int.Parse(coordinatesB[0]);
        int y2 = int.Parse(coordinatesB[1]);

        double distance = Math.Sqrt(Math.Pow(x2-x1,2) + Math.Pow(y2-y1,2));
        Console.WriteLine("点A(" + x1 + "," + y1 + ")和点B(" + x2 + "," + y2 + ")之间的欧几里得距离为：" + distance);
