function [slope, intercept, r_squared, mse] = recursive_linear_regression(x, y, alpha, slope_0, intercept_0)
% Perform linear regression using recursive formula
% Inputs:
%   x: independent variable
%   y: dependent variable
%   alpha: learning rate
%   slope_0: initial slope
%   intercept_0: initial intercept
% Outputs:
%   slope: final slope
%   intercept: final intercept
%   r_squared: R-squared
%   mse: mean squared error

% Initialize variables
n = length(x);
slope = slope_0;
intercept = intercept_0;
y_pred = slope * x + intercept;
ss_tot = sum((y - mean(y)).^2);
ss_res = sum((y - y_pred).^2);

