#include "uv.h"
#include "file_data.pb.h"

using namespace std;
namespace fs = std::filesystem;

const int BUFFER_SIZE = 1024 * 1024;

// Callback for file read
static void on_read(uv_fs_t *req);

// Send file data and metadata to remote host
void send_file(string fname, uv_tcp_t* socket, file_data::FileData& fileData)
{
    uv_buf_t buf;
    uv_fs_t fileReq;

    uv_fs_open(uv_default_loop(), &fileReq, fname.c_str(), O_RDONLY, 0, NULL);

    buf = uv_buf_init((char*)malloc(BUFFER_SIZE), BUFFER_SIZE);

    uv_fs_read(uv_default_loop(), &fileReq, &buf, 1, 0, on_read);

    // Wait for file read to complete
    uv_run(uv_default_loop(), UV_RUN_DEFAULT);

    // Send file data
    uv_write_t req;
    uv_buf_t writebuf;
    writebuf = uv_buf_init((char*)fileData.SerializeAsString().c_str(), fileData.ByteSize());
    req.data = (void*)writebuf.base;
    uv_write(&req, (uv_stream_t*)socket, &writebuf, 1, NULL);

    cout << "File sent: " << fname << endl;

    // Clean up
    uv_fs_close(uv_default_loop(), &fileReq, NULL);
    free(buf.base);
}

// Callback for file read
static void on_read(uv_fs_t *req)
{
    if (req->result < 0)
    {
        cout << "Error reading file: " << uv_strerror(req->result) << endl;
    }
    else if (req->result == 0)
    {
        uv_fs_req_cleanup(req);
    }
    else
    {
        uv_fs_write(uv_default_loop(), &req->fs_req, 1, req->buf, req->result, -1, NULL);
        uv_fs_read(uv_default_loop(), req, &req->buf, 1, -1, on_read);
    }
}

// Send directory contents to remote host
void send_folder(string folderPath, uv_tcp_t* socket)
{
    auto dirIter = fs::directory_iterator(folderPath);

    for (auto& file : dirIter)
    {
        if (fs::is_regular_file(file))
        {
            file_data::FileData fileData;
            fileData.set_file_path(file.path().string());
            fileData.set_modified_time(fs::last_write_time(file));
            fileData.set_file_size(fs::file_size(file));
            send_file(file.path().string(), socket, fileData);
        }
    }
}

// Callback for TCP connection
static void on_connect(uv_connect_t *req, int status)
{
    if (status < 0)
    {
        cout << "Failed to connect: " << uv_strerror(status) << endl;
    }
    else
    {
        uv_tcp_t* socket = (uv_tcp_t*)req->handle;

        cout << "Connected!" << endl;

        // Send folder contents
        send_folder("path/to/folder", socket);

        // Close socket
        uv_shutdown_t* shutdown_req = new uv_shutdown_t;
        shutdown_req->data = (void*)socket;
        uv_shutdown(shutdown_req, (uv_stream_t*)socket, [](uv_shutdown_t* req, int status){
            uv_close((uv_handle_t*)req->data, NULL);
            delete req;
        });
    }

    delete req;
}

int main()
{
    uv_loop_t *loop = uv_default_loop();

    uv_tcp_t* socket = new uv_tcp_t;
    uv_tcp_init(loop, socket);

    sockaddr_in dest;
    uv_ip4_addr("127.0.0.1", 12345, &dest);

    uv_connect_t* connect_req = new uv_connect_t;
    uv_tcp_connect(connect_req, socket, (const sockaddr*)&dest, on_connect);

    uv_run(loop, UV_RUN_DEFAULT);

    uv_loop_close(loop);

    return 0;
}
