```c++
#include <iostream>
#include <vector>
#include <random>

// 地形类型
enum TerrainType {
    TERRAIN_GRASS,
    TERRAIN_WATER,
    TERRAIN_MOUNTAIN,
    TERRAIN_DESERT
};

// 文明类型
enum CivilizationType {
    CIVILIZATION_HUMAN,
    CIVILIZATION_ELF,
    CIVILIZATION_DWARF,
    CIVILIZATION_ORC
};

// 动物类型
enum AnimalType {
    ANIMAL_WOLF,
    ANIMAL_BEAR,
    ANIMAL_DEER,
    ANIMAL_RABBIT
};

// 植物类型
enum PlantType {
    PLANT_TREE,
    PLANT_FLOWER,
    PLANT_GRASS,
    PLANT_CACTUS
};

// 地图格子
struct MapCell {
    TerrainType terrain;
    CivilizationType civilization;
    AnimalType animal;
    PlantType plant;
};

// 障碍物
struct Obstacle {
    int x;
    int y;
    std::string description;
};

// 地图大小
const int MAP_WIDTH = 10;
const int MAP_HEIGHT = 10;

// 随机数生成器
std::random_device rd;
std::mt19937 gen(rd());

// 随机生成地形
TerrainType generateTerrain() {
    std::uniform_int_distribution<> dis(0, 3);
    return static_cast<TerrainType>(dis(gen));
}

// 随机生成文明
CivilizationType generateCivilization() {
    std::uniform_int_distribution<> dis(0, 3);
    return static_cast<CivilizationType>(dis(gen));
}

// 随机生成动物
AnimalType generateAnimal() {
    std::uniform_int_distribution<> dis(0, 3);
    return static_cast<AnimalType>(dis(gen));
}

// 随机生成植物
PlantType generatePlant() {
    std::uniform_int_distribution<> dis(0, 3);
    return static_cast<PlantType>(dis(gen));
}

// 生成地图
std::vector<std::vector<MapCell>> generateMap() {
    std::vector<std::vector<MapCell>> map(MAP_HEIGHT, std::vector<MapCell>(MAP_WIDTH));
    for (int y = 0; y < MAP_HEIGHT; y++) {
        for (int x = 0; x < MAP_WIDTH; x++) {
            map[y][x].terrain = generateTerrain();
            map[y][x].civilization = generateCivilization();
            map[y][x].animal = generateAnimal();
            map[y][x].plant = generatePlant();
        }
    }
    return map;
}

// 生成障碍物
std::vector<Obstacle> generateObstacles(const std::vector<std::vector<MapCell>>& map) {
    std::vector<Obstacle> obstacles;
    std::uniform_int_distribution<> dis(0, MAP_WIDTH * MAP_HEIGHT - 1);
    for (int i = 0; i < 5; i++) {
        int index = dis(gen);
        int x = index % MAP_WIDTH;
        int y = index / MAP_WIDTH;
        Obstacle obstacle;
        obstacle.x = x;
        obstacle.y = y;
        obstacle.description = "Obstacle " + std::to_string(i);
        obstacles.push_back(obstacle);
    }
    return obstacles;
}

// 显示地图
void displayMap(const std::vector<std::vector<MapCell>>& map) {
    for (int y = 0; y < MAP_HEIGHT; y++) {
        for (int x = 0; x < MAP_WIDTH; x++) {
            std::cout << map[y][x].terrain << " ";
        }
        std::cout << std::endl;
    }
}

// 显示障碍物
void displayObstacles(const std::vector<Obstacle>& obstacles) {
    for (const auto& obstacle : obstacles) {
        std::cout << obstacle.description << " at (" << obstacle.x << ", " << obstacle.y << ")" << std::endl;
    }
}

int main() {
    std::vector<std::vector<MapCell>> map = generateMap();
    std::vector<Obstacle> obstacles = generateObstacles(map);
    displayMap(map);
    displayObstacles(obstacles);
    return 0;
}
```

这个程序使用了C++的随机数生成器来生成随机的地形、文明、动物和植物。它还生成了一些障碍物，这些障碍物可以用于模拟一个穿越这个未知领域的团队遇到的障碍。最后，它将地图和障碍物显示在控制台上。

