```go
package main

import (
    "encoding/json"
    "fmt"
    "io/ioutil"
    "net/http"
)

func main() {
    url := "https://maps.googleapis.com/maps/api/place/nearbysearch/json?location=37.7749,-122.4194&radius=5000&type=restaurant&keyword=mexican&key=YOUR_API_KEY"

    resp, err := http.Get(url)
    if err != nil {
        panic(err)
    }
    defer resp.Body.Close()

    body, err := ioutil.ReadAll(resp.Body)
    if err != nil {
        panic(err)
    }

    var data map[string]interface{}
    err = json.Unmarshal(body, &data)
    if err != nil {
        panic(err)
    }

    fmt.Println(data)
}
```

在这个示例中，我们使用http.Get函数发送HTTP GET请求，并使用ioutil.ReadAll函数读取响应体。然后，我们使用json.Unmarshal函数将JSON响应解析为一个map[string]interface{}类型的变量。最后，我们打印出这个变量以查看响应数据。请注意，您需要将YOUR_API_KEY替换为您自己的API密钥。

