以下是一个实现这些要求的代码片段：

```html
<!DOCTYPE html>
<html>
<head>
	<title>Human Evolution Timeline</title>
	<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/vis/4.21.0/vis.min.css">
	<script src="https://cdnjs.cloudflare.com/ajax/libs/vis/4.21.0/vis.min.js"></script>
	<style>
		#timeline {
			height: 500px;
			margin: 50px auto;
		}
	</style>
</head>
<body>
	<div id="timeline"></div>

	<script>
		// Define the events
		var events = new vis.DataSet([
			{id: 1, content: 'Australopithecus', start: '4.2 million years ago', end: '2.9 million years ago', group: 'early hominids'},
			{id: 2, content: 'Homo habilis', start: '2.8 million years ago', end: '1.5 million years ago', group: 'early hominids'},
			{id: 3, content: 'Homo erectus', start: '1.9 million years ago', end: '143,000 years ago', group: 'early humans'},
			{id: 4, content: 'Neanderthals', start: '400,000 years ago', end: '40,000 years ago', group: 'early humans'},
			{id: 5, content: 'Homo sapiens', start: '300,000 years ago', end: 'present', group: 'modern humans'}
		]);

		// Define the groups
		var groups = new vis.DataSet([
			{id: 'early hominids', content: 'Early Hominids'},
			{id: 'early humans', content: 'Early Humans'},
			{id: 'modern humans', content: 'Modern Humans'}
		]);

		// Define the options
		var options = {
			height: '500px',
			start: '4.2 million years ago',
			end: 'present',
			groupOrder: 'content',
			editable: false,
			onInitialDrawComplete: function() {
				// Add hover events to the items
				var items = document.getElementsByClassName('vis-item');
				for (var i = 0; i < items.length; i++) {
					items[i].addEventListener('mouseover', function() {
						var itemId = this.getAttribute('data-item');
						var item = events.get(itemId);
						var content = '<h3>' + item.content + '</h3>';
						content += '<p>Start: ' + item.start + '</p>';
						content += '<p>End: ' + item.end + '</p>';
						document.getElementById('event-info').innerHTML = content;
					});
					items[i].addEventListener('mouseout', function() {
						document.getElementById('event-info').innerHTML = '';
					});
				}
			}
		};

		// Create the timeline
		var timeline = new vis.Timeline(document.getElementById('timeline'), events, groups, options);

		// Add filter buttons
		var filterButtons = document.createElement('div');
		filterButtons.innerHTML = '<button onclick="filterEvents(\'early hominids\')">Early Hominids</button> <button onclick="filterEvents(\'early humans\')">Early Humans</button> <button onclick="filterEvents(\'modern humans\')">Modern Humans</button>';
		document.body.insertBefore(filterButtons, document.getElementById('timeline'));

		// Add event info panel
		var eventInfo = document.createElement('div');
		eventInfo.id = 'event-info';
		document.body.insertBefore(eventInfo, document.getElementById('timeline'));

		// Function to filter events by group
		function filterEvents(group) {
			if (group === 'all') {
				timeline.setGroups(groups);
				timeline.setItems(events);
			} else {
				var filteredGroups = new vis.DataSet(groups.get({
					filter: function(item) {
						return item.id === group;
					}
				}));
				var filteredEvents = new vis.DataSet(events.get({
					filter: function(item) {
						return item.group === group;
					}
				}));
				timeline.setGroups(filteredGroups);
				timeline.setItems(filteredEvents);
			}
		}
	</script>
</body>
</html>
