// 定义垃圾桶类
class TrashCan {
    public string name; // 垃圾桶名称
    public int capacity; // 垃圾桶容量
    public int currentAmount; // 当前垃圾桶中的垃圾数量

    // 构造函数
    public TrashCan(string name, int capacity) {
        this.name = name;
        this.capacity = capacity;
        this.currentAmount = 0;
    }

    // 将垃圾放入垃圾桶
    public void AddTrash(int amount) {
        currentAmount += amount;
        if (currentAmount >= capacity) {
            Console.WriteLine("Warning: " + name + " is almost full!");
        }
    }
}

// 定义物品类
class Item {
    public string name; // 物品名称
    public string[] materials; // 物品材料

    // 构造函数
    public Item(string name, string[] materials) {
        this.name = name;
        this.materials = materials;
    }
}

// 定义垃圾分类器类
class TrashClassifier {
    public TrashCan plasticCan;
    public TrashCan paperCan;
    public TrashCan glassCan;
    public TrashCan metalCan;

    // 构造函数
    public TrashClassifier() {
        plasticCan = new TrashCan("Plastic", 100);
        paperCan = new TrashCan("Paper", 100);
        glassCan = new TrashCan("Glass", 100);
        metalCan = new TrashCan("Metal", 100);
    }

    // 将物品放入相应的垃圾桶
    public void ClassifyItem(Item item) {
        foreach (string material in item.materials) {
            switch (material) {
                case "plastic":
                    plasticCan.AddTrash(1);
                    break;
                case "paper":
                    paperCan.AddTrash(1);
                    break;
                case "glass":
                    glassCan.AddTrash(1);
                    break;
                case "metal":
                    metalCan.AddTrash(1);
                    break;
            }
        }
    }
}

