using System;

class Program
{
    static void Main(string[] args)
    {
        // 定义属性权重和感官评估权重
        double hardnessWeight = 0.3;
        double viscosityWeight = 0.2;
        double pHWeight = 0.1;
        double microbialActivityWeight = 0.1;
        double consumerPreferenceWeight = 0.3;

        // 定义每种冷却方法的属性值和感官评估值
        double[] liquidNitrogenValues = { 8.5, 0.05, 6.8, 0.02, 9.0 };
        double[] dryIceValues = { 7.2, 0.08, 6.5, 0.05, 7.5 };
        double[] iceBathValues = { 6.5, 0.1, 7.0, 0.1, 8.5 };

        // 计算每种冷却方法的总分数
        double liquidNitrogenScore = CalculateScore(liquidNitrogenValues, hardnessWeight, viscosityWeight, pHWeight, microbialActivityWeight, consumerPreferenceWeight);
        double dryIceScore = CalculateScore(dryIceValues, hardnessWeight, viscosityWeight, pHWeight, microbialActivityWeight, consumerPreferenceWeight);
        double iceBathScore = CalculateScore(iceBathValues, hardnessWeight, viscosityWeight, pHWeight, microbialActivityWeight, consumerPreferenceWeight);

        // 输出结果
        Console.WriteLine("Liquid Nitrogen Score: " + liquidNitrogenScore);
        Console.WriteLine("Dry Ice Score: " + dryIceScore);
        Console.WriteLine("Ice Bath Score: " + iceBathScore);
    }

    // 计算总分数的函数
    static double CalculateScore(double[] values, double hardnessWeight, double viscosityWeight, double pHWeight, double microbialActivityWeight, double consumerPreferenceWeight)
    {
        double hardness = values[0];
        double viscosity = values[1];
        double pH = values[2];
        double microbialActivity = values[3];
        double consumerPreference = values[4];

        double score = hardnessWeight * hardness + viscosityWeight * viscosity + pHWeight * pH + microbialActivityWeight * microbialActivity + consumerPreferenceWeight * consumerPreference;

        return score;
    }
}

在这个程序中，我们首先定义了每个属性和感官评估的权重。然后，我们定义了每种冷却方法的属性值和感官评估值。接下来，我们使用CalculateScore函数计算每种冷却方法的总分数，该函数将每个属性的值乘以其权重并将它们相加。最后，我们输出每种冷却方法的总分数。

由于Yelp API需要进行身份验证，因此需要先注册一个Yelp开发者账户并获取API密钥。以下是一个使用Yelp API和C++编程语言创建脚本的示例代码：

```c++
#include <iostream>
#include <string>
#include <curl/curl.h>
#include <jsoncpp/json/json.h>

using namespace std;

// Yelp API密钥
const string API_KEY = "YOUR_API_KEY_HERE";

// Yelp API搜索URL
const string SEARCH_URL = "https://api.yelp.com/v3/businesses/search";

// 搜索参数
const string TERM = "italian";
const string LOCATION = "Manhattan";
const string SORT_BY = "rating";
const int LIMIT = 5;

// 价格范围
const string PRICE = "2,3";

// 执行HTTP GET请求并返回响应
string httpGet(string url, string authHeader) {
    CURL *curl;
    CURLcode res;
    string response;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, authHeader.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](char *ptr, size_t size, size_t nmemb, string *data) {
            data->append(ptr, size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);
    }

    return response;
}

int main() {
    // 构造HTTP请求头
    string authHeader = "Authorization: Bearer " + API_KEY;

    // 构造搜索URL
    string searchUrl = SEARCH_URL + "?term=" + TERM + "&location=" + LOCATION + "&sort_by=" + SORT_BY + "&limit=" + to_string(LIMIT) + "&price=" + PRICE;

    // 执行HTTP GET请求并获取响应
    string response = httpGet(searchUrl, authHeader);

    // 解析JSON响应
    Json::Value root;
    Json::CharReaderBuilder builder;
    Json::CharReader *reader = builder.newCharReader();
    string errors;
    bool parsingSuccessful = reader->parse(response.c_str(), response.c_str() + response.size(), &root, &errors);
    delete reader;

    if (parsingSuccessful) {
        // 遍历搜索结果并输出重要信息
        for (int i = 0; i < root["businesses"].size(); i++) {
            Json::Value business = root["businesses"][i];
            cout << "Name: " << business["name"].asString() << endl;
            cout << "Address: " << business["location"]["address1"].asString() << endl;
            cout << "Phone: " << business["phone"].asString() << endl;
            cout << "Rating: " << business["rating"].asFloat() << endl;
            cout << endl;
        }
    } else {
        cout << "Failed to parse JSON response: " << errors << endl;
    }

    return 0;
}
```

该脚本使用libcurl库执行HTTP GET请求，并使用jsoncpp库解析JSON响应。它构造了一个包含搜索参数的Yelp API搜索URL，并使用API密钥构造了一个HTTP请求头。它还使用Yelp API的价格参数过滤搜索结果，并遍历搜索结果以输出重要信息。

