import json

# 从JSON文件中读取调查提示
def load_survey(filename):
    with open(filename, 'r') as f:
        survey = json.load(f)
    return survey

# 显示调查提示并收集用户回答
def take_survey(survey):
    answers = {}
    for question in survey['questions']:
        print(question['text'])
        for i, option in enumerate(question['options']):
            print(f"{i+1}. {option}")
        while True:
            try:
                answer = int(input("请输入您的答案："))
                if answer < 1 or answer > len(question['options']):
                    raise ValueError
                break
            except ValueError:
                print("无效的答案选项，请重新输入。")
        answers[question['id']] = answer
    return answers

# 显示用户回答并允许修改
def review_answers(survey, answers):
    print("您的回答如下：")
    for question in survey['questions']:
        print(question['text'])
        answer = question['options'][answers[question['id']] - 1]
        print(f"您的答案是：{answer}")
        while True:
            edit = input("是否要修改您的答案？(y/n)")
            if edit.lower() == 'y':
                while True:
                    try:
                        new_answer = int(input("请输入新的答案选项："))
                        if new_answer < 1 or new_answer > len(question['options']):
                            raise ValueError
                        break
                    except ValueError:
                        print("无效的答案选项，请重新输入。")
                answers[question['id']] = new_answer
                break
            elif edit.lower() == 'n':
                break
            else:
                print("无效的输入，请输入'y'或'n'。")

# 将用户回答保存为JSON文件
def save_answers(filename, answers):
    with open(filename, 'w') as f:
        json.dump(answers, f)

# 测试程序
survey = load_survey('survey.json')
answers = take_survey(survey)
review_answers(survey, answers)
save_answers('answers.json', answers)
```

在这个程序中，`load_survey`函数从JSON文件中读取调查提示，`take_survey`函数显示提示并收集用户回答，`review_answers`函数显示用户回答并允许修改，`save_answers`函数将用户回答保存为JSON文件。

程序还包括一些错误处理，例如处理无效的答案选项和无效的用户输入。在`review_answers`函数中，用户可以选择修改他们的回答，直到他们满意为止。

