代码如下：
```
import java.util.Scanner;
public class MatrixMultiplication {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.println("Enter the size of the first matrix: ");
        System.out.print("Rows: ");
        int rows1 = input.nextInt();
        System.out.print("Columns: ");
        int columns1 = input.nextInt();
        System.out.println("Enter the elements of the first matrix: ");
        int[][] matrix1 = new int[rows1][columns1];
        for (int i = 0; i < rows1; i++) {
            for (int j = 0; j < columns1; j++) {
                matrix1[i][j] = input.nextInt();
            }
        }
        System.out.println("Enter the size of the second matrix: ");
        System.out.print("Rows: ");
        int rows2 = input.nextInt();
        System.out.print("Columns: ");
        int columns2 = input.nextInt();
        System.out.println("Enter the elements of the second matrix: ");
        int[][] matrix2 = new int[rows2][columns2];
        for (int i = 0; i < rows2; i++) {
            for (int j = 0; j < columns2; j++) {
                matrix2[i][j] = input.nextInt();
            }
        }
        if (columns1 != rows2) {
            System.out.println("Cannot multiply matrices of these sizes.");
        } else {
            int[][] product = new int[rows1][columns2];
            for (int i = 0; i < rows1; i++) {
                for (int j = 0; j < columns2; j++) {
                    int sum = 0;
                    for (int k = 0; k < columns1; k++) {
                        sum += matrix1[i][k] * matrix2[k][j];
                    }
                    product[i][j] = sum;
                }
            }
            System.out.println("Product of matrices is: ");
            for (int i = 0; i < rows1; i++) {
                for (int j = 0; j < columns2; j++) {
                    System.out.print(product[i][j] + " ");
                }
                System.out.println();
            }
        }
    }
}
```
